import{c as e,Q as r,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"實作專案","description":"","frontmatter":{},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md","lastUpdated":1785912489000}'),s={name:"projects/index.md"};function n(i,t,c,l,d,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="實作專案" tabindex="-1">實作專案 <a class="header-anchor" href="#實作專案" aria-label="Permalink to &quot;實作專案&quot;">​</a></h1><p>本課程的實作專案讓你從「看懂理論」進入「動手建立」。每個專案都有具體的任務清單、參考實作和可驗證的驗收標準。</p><p>四個專案是一條連續的路徑：<strong>建立 workspace → 設計 harness → 把驗證變成資產 → 推廣成基礎建設</strong>。</p><h2 id="專案清單" tabindex="-1">專案清單 <a class="header-anchor" href="#專案清單" aria-label="Permalink to &quot;專案清單&quot;">​</a></h2><h3 id="project-01-從零建立你的第一個-workspace" tabindex="-1"><a href="/cc-workspace-docs/projects/project-01-init-workspace/">Project 01：從零建立你的第一個 Workspace</a> <a class="header-anchor" href="#project-01-從零建立你的第一個-workspace" aria-label="Permalink to &quot;[Project 01：從零建立你的第一個 Workspace](/projects/project-01-init-workspace/)&quot;">​</a></h3><p>建立一個能跨 session 記憶、自動初始化環境、有明確驗收定義的完整工作環境。含對照實驗（有／無 CLAUDE.md）與定期審閱機制。</p><p><strong>前置課程</strong>：Lecture 01、02、05 <strong>產出</strong>：CLAUDE.md、claude-progress.md、feature_list.json、SessionStart / Stop hooks</p><hr><h3 id="project-02-設計你的-harness" tabindex="-1"><a href="/cc-workspace-docs/projects/project-02-harness-design/">Project 02：設計你的 Harness</a> <a class="header-anchor" href="#project-02-設計你的-harness" aria-label="Permalink to &quot;[Project 02：設計你的 Harness](/projects/project-02-harness-design/)&quot;">​</a></h3><p>設計並實作 Planner / Generator / Evaluator 三層架構，加上獨立的對抗性 verifier 與安全 hooks。含 Oracle 先驗與 gate 選擇稽核。</p><p><strong>前置課程</strong>：Lecture 03、04、06 <strong>產出</strong>：Planner 提示詞、<code>scripts/evaluate.sh</code>、adversarial verifier agent、PreToolUse security hook</p><hr><h3 id="project-03-把驗證編碼成-skill" tabindex="-1"><a href="/cc-workspace-docs/projects/project-03-verification-skill/">Project 03：把驗證編碼成 Skill</a> <a class="header-anchor" href="#project-03-把驗證編碼成-skill" aria-label="Permalink to &quot;[Project 03：把驗證編碼成 Skill](/projects/project-03-verification-skill/)&quot;">​</a></h3><p>把 Project 02 的 shell 腳本升級成可重用、可被 Claude 主動呼叫的 Skill。走一遍評估驅動開發與 Claude A / Claude B 迭代法。</p><p><strong>前置課程</strong>：Lecture 07、10 <strong>產出</strong>：驗證 Skill（含 Progressive Disclosure 結構）、3 個評估場景與 baseline、迭代記錄</p><hr><h3 id="project-04-plugin-化與自動化治理" tabindex="-1"><a href="/cc-workspace-docs/projects/project-04-plugin-automation/">Project 04：Plugin 化與自動化治理</a> <a class="header-anchor" href="#project-04-plugin-化與自動化治理" aria-label="Permalink to &quot;[Project 04：Plugin 化與自動化治理](/projects/project-04-plugin-automation/)&quot;">​</a></h3><p>把前三個專案的成果打包成可分發的 Plugin，接上排程或事件觸發的自動化，補上成本與安全護欄。</p><p><strong>前置課程</strong>：Lecture 11、12 <strong>產出</strong>：可安裝的 Plugin、一個運作中的 Routine 或 GitHub Actions、憑證隔離設定、審閱機制</p><hr><h2 id="對照表" tabindex="-1">對照表 <a class="header-anchor" href="#對照表" aria-label="Permalink to &quot;對照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>專案</th><th>解決的問題</th><th>完成後你能說</th></tr></thead><tbody><tr><td>01</td><td>Claude 每次都要重新告知專案規則</td><td>「新 session 開起來它就知道」</td></tr><tr><td>02</td><td>Claude 宣布完成但實際沒完成</td><td>「它宣布完成時，我有獨立證據」</td></tr><tr><td>03</td><td>驗證綁在一個專案、要我記得跑</td><td>「驗證是資產，會自己在對的時機發動」</td></tr><tr><td>04</td><td>只有我的機器上有這套設定</td><td>「團隊裝一個 plugin 就有相同的護欄」</td></tr></tbody></table><h2 id="學習建議" tabindex="-1">學習建議 <a class="header-anchor" href="#學習建議" aria-label="Permalink to &quot;學習建議&quot;">​</a></h2><ol><li><strong>按順序完成</strong>：每個專案都建立在前一個的產出上。</li><li><strong>用你自己的實際專案</strong>：比用範例專案學得快得多，而且產出立刻可用。</li><li><strong>記錄失敗</strong>：每個失敗都是 Ratchet 原則的素材——規則應該追蹤到一次具體的失敗。</li><li><strong>從小開始</strong>：先建立最小可用 Harness，再逐步迭代。</li><li><strong>注意可刪與不可刪的邊界</strong>：程序性鷹架會隨模型進化而過時，<strong>驗證閘門與不可逆操作確認不會</strong>。每次審閱都重新確認這條線。</li></ol>',24)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
